var i=`0590-qorma`;var o=`world-0590`;var t=`AF`;var a=`south-asia`;var r=4;var s=111;var g={en:`Qorma`,ua:`Корма`};var d={en:`A traditional dish from Afghanistan, centered on lamb, yellow onion, tomato, cilantro. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Афганістан. Основні складники: ягнятина, жовта цибуля, помідор, кінза. Домашній варіант із кількостями продуктів за етапами приготування.`};var l=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 13 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 13 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:13,i:[[`lamb`,720,`g`],[`yellow-onion`,250,`g`],[`sunflower-oil`,60,`ml`]]},{en:`Add the braising liquid and seasonings, cover and cook gently for about 95 minutes until the meat is tender and safely cooked.`,ua:`Додайте рідину та приправи для тушкування, накрийте кришкою й готуйте на малому вогні приблизно 95 хвилин до м’якості та повної готовності м’яса.`,t:[`braising`],m:95,i:[[`tomato`,380,`g`],[`water`,900,`ml`],[`ground-turmeric`,4,`g`],[`ground-coriander`,5,`g`],[`ground-cumin`,4,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,25,`g`]]}];var m={slug:i,id:o,country:`AF`,region:a,servings:4,minutes:111,title:g,text:d,steps:l};export{t as country,m as default,o as id,s as minutes,a as region,r as servings,i as slug,l as steps,d as text,g as title};